            ClosureReceiving::acquire(&function, &mut budget).unwrap()
        });
        assert!(!expired.valid(&function, &budget));
        assert!(!expired.valid(&function, &budget));
        drop(expired);
        drop(budget);
    });
    assert!(!allocation.invalid && allocation.live == 0);
    assert_eq!(allocation.allocated, allocation.freed);
}

